mapper.select:
SELECT *
FROM comments
WHERE post_id = #{postId}
  AND parent_id = 0

  AND (create_time < #{cursorCreateTime}
       OR (create_time = #{cursorCreateTime} AND comment_id < #{cursorCommentId}))

ORDER BY create_time DESC, comment_id DESC
LIMIT #{limit}

SELECT *
FROM comments
WHERE root_id = #{rootId}
  AND parent_id != 0

  AND (create_time < #{cursorCreateTime}
       OR (create_time = #{cursorCreateTime} AND comment_id < #{cursorCommentId}))

ORDER BY create_time DESC, comment_id DESC
LIMIT #{limit}

mapper.update:
UPDATE comments
SET status = 1,
    update_time = NOW(3)
WHERE comment_id = #{commentId}
  AND creator_id = #{creatorId}
  AND status = 0

mapper.select:
SELECT comment_id
FROM comments

    status = 0

        AND comment_id > #{cursorCommentId}


ORDER BY comment_id ASC
LIMIT #{limit}
